-- =============================================================================
-- Demo catalogue (docs/11 §6–§7) — LOCAL AND STAGING ONLY.
--
-- Production gets the real catalogue (docs/11 preamble). Brand names are used as
-- realistic fixtures; logos and photography are placeholders and MUST be replaced with
-- authorised assets before launch (docs/11 §5).
--
-- Idempotent: fixed UUIDs plus `on conflict do update`, so `db reset` and repeated
-- `db push --include-seed` produce identical state.
--
-- Content note: descriptions here are 2–3 sentences. docs/11 §7 asks for ~120 words per
-- product; expanding them is content work, not schema work, and is tracked in
-- docs/14 §3. Every claim below stays inside the permissible-function wording of
-- docs/08 §7.2 — no treats/cures/prevents anywhere.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Ingredients (docs/11 §6)
-- -----------------------------------------------------------------------------
on conflict (id) do update set slug = excluded.slug, name = excluded.name, summary = excluded.summary,
  benefits = excluded.benefits, dosage_notes = excluded.dosage_notes, safety_notes = excluded.safety_notes,
  evidence = excluded.evidence, category = excluded.category;

-- -----------------------------------------------------------------------------
-- Products (docs/11 §7)
-- -----------------------------------------------------------------------------
on conflict (id) do update set slug = excluded.slug, brand_id = excluded.brand_id, name = excluded.name,
  subtitle = excluded.subtitle, description = excluded.description, how_to_use = excluded.how_to_use,
  warnings = excluded.warnings, form = excluded.form, serving_size = excluded.serving_size,
  dietary_tags = excluded.dietary_tags, status = excluded.status, is_featured = excluded.is_featured,
  published_at = excluded.published_at;
